import numpy as np

def solve_refined():
    max_s = 0
    # We want to maximize S = y + (16xy + sqrt(32x^2y(8y - (x+y)^2))) / (x+y)^2
    # Let's test some values.
    for y in np.linspace(0.1, 7.9, 5000):
        limit_x = np.sqrt(8*y) - y
        if limit_x > 0:
            # Try x = limit_x / 2 and some other values
            # Let's also try to find the max x for each y.
            # Actually, let's just test a few x values for each y.
            for x in np.linspace(0.1, limit_x, 100):
                D = 32 * x**2 * y * (8*y - (x+y)**2)
                if D >= 0:
                    z = (16*x*y - x*(x+y)**2 + np.sqrt(D)) / (x+y)**2
                    if z > 0:
                        max_s = max(max_s, x + y + z)
    return max_s

print(solve_refined())

